/* Local per-Universe arrangement. No native persistence is implied. */
(function(){
'use strict';
const ids=['bloom','aurora','cosmic','arcade','solstice','metro','sakura','abyss','prism','atlas','cassette','relay','loom','kinetic','tide'];
const slots=['hero','apps','pins','recents'],labelKeys=['hero','apps','pins','recents'];
const panels=['.hero','.ob-apps-panel','.ob-pins-panel','.ob-recents-panel'].map(s=>document.querySelector(s));
const header=document.querySelector('.topline'),key='ob.universe.arrangements.v1';
if(!header||panels.some(p=>!p))return;
let current='',active=false,selected=-1,dragged=-1,undo=null,layouts={};let scrollFrame=0,scrollDirection=0,scrollTime=0;
function stopScroll(){cancelAnimationFrame(scrollFrame);scrollFrame=0;scrollDirection=0;scrollTime=0}
function scrollStep(time){scrollFrame=0;if(!active||dragged<0||!scrollDirection||document.hidden||document.querySelector('dialog[open]')){stopScroll();return}const dt=scrollTime?Math.min(50,time-scrollTime):16;scrollTime=time;const previous=scrollY;scrollBy(0,scrollDirection*dt*.6);if(scrollY!==previous)scrollFrame=requestAnimationFrame(scrollStep);else stopScroll()}
function edgeScroll(e){if(!active||dragged<0)return;const edge=Math.min(120,innerHeight*.1),direction=e.clientY<edge?-1:e.clientY>innerHeight-edge?1:0;if(!direction){stopScroll();return}scrollDirection=direction;if(!scrollFrame)scrollFrame=requestAnimationFrame(scrollStep)}
try{const raw=localStorage.getItem(key);if(raw&&raw.length<=4096){const data=JSON.parse(raw);if(data&&data.version===1&&data.layouts&&typeof data.layouts==='object')for(const id of ids){const a=data.layouts[id];if(Array.isArray(a)&&a.length===4&&new Set(a).size===4&&a.every(s=>slots.includes(s)))layouts[id]=a.slice()}}}catch(_){}
const english={"arrange":"Arrange","done":"Done","reset":"Reset layout","undo":"Undo","region":"Arrange this Universe","moveHero":"Move Search","moveApps":"Move Apps","movePins":"Move Pinned sites","moveRecents":"Move Recent sites","hero":"Search","apps":"Apps","pins":"Pinned sites","recents":"Recent sites","selected":"{panel} selected. Choose another panel to swap, or press Escape to cancel.","instructions":"Drag a handle onto another, or select two handles to swap. Changes stay on this device.","saved":"Layout saved on this device.","unsaved":"Layout changed for this visit; device storage is unavailable.","resetSaved":"Original layout restored on this device.","resetUnsaved":"Original layout restored for this visit; device storage is unavailable.","undoSaved":"Previous layout restored on this device.","undoUnsaved":"Previous layout restored for this visit; device storage is unavailable.","cancelled":"Move cancelled.","arranging":"Arranging {universe}. Drag a handle or select two panels to swap."};
const languages=['ar','de','en','es','fr','hi','id','it','ja','ko','nl','pl','pt-BR','ru','th','tr','vi','zh-Hans','zh-Hant'],catalogs=new Map([['en',english]]),pending=new Map(),failed=new Set(),catalogBase=new URL('./arrange-locales/',document.currentScript.src);
let copyLocale='en',copyLive=true,lastMessage=null;
function validLanguage(value){return typeof value==='string'&&languages.includes(value)?value:null}
function hostLanguage(){try{return validLanguage(window.omnibloomHost?.getLanguage?.())}catch(_){return null}}
copyLocale=validLanguage(new URLSearchParams(location.search).get('lang'))||hostLanguage()||validLanguage(document.documentElement.lang)||'en';
function activeLanguage(){return catalogs.has(copyLocale)?copyLocale:'en'}
function text(id,args={}){return (catalogs.get(activeLanguage())[id]||english[id]||'').replace(/\{(panel|universe)\}/g,(_,name)=>name==='panel'?text(labelKeys[args.panel]):String(args[name]??''))}
function mark(node){node.lang=activeLanguage();node.dir=node.lang==='ar'?'rtl':'ltr';node.dataset.copyLocale=node.lang;node.dataset.copyReview=node.lang==='en'?'source':'native-review-required';node.dataset.copyFallback=String(node.lang!==copyLocale)}
function renderCopy(){if(!copyLive)return;for(const [node,id] of [[toggle,'arrange'],[done,'done'],[reset,'reset'],[back,'undo']]){node.textContent=text(id);mark(node)}bar.setAttribute('aria-label',text('region'));mark(bar);handles.forEach((h,i)=>{h.textContent=text(['moveHero','moveApps','movePins','moveRecents'][i]);mark(h)});if(lastMessage){status.textContent=text(lastMessage.id,lastMessage.args);mark(status)}}
function checkCatalog(data,lang){if(!data||data.schema!==1||data.locale!==lang||data.nativeReviewRequired!==(lang!=='en')||!data.strings||Object.keys(data.strings).length!==Object.keys(english).length)return false;return Object.keys(english).every(k=>typeof data.strings[k]==='string'&&data.strings[k].length>0&&data.strings[k].length<1200&&JSON.stringify(data.strings[k].match(/\{\w+\}/g)||[])===JSON.stringify(english[k].match(/\{\w+\}/g)||[]))}
function loadCopy(retry=false){const lang=copyLocale;if(!copyLive||catalogs.has(lang)||pending.has(lang)||failed.has(lang)&&!retry)return;failed.delete(lang);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);pending.set(lang,controller);fetch(new URL(lang+'.json',catalogBase),{signal:controller.signal,credentials:'omit',cache:'force-cache'}).then(r=>{if(!r.ok)throw Error('catalog unavailable');return r.json()}).then(data=>{if(!checkCatalog(data,lang))throw Error('invalid catalog');catalogs.set(lang,Object.freeze(data.strings))}).catch(()=>{if(!controller.signal.aborted)failed.add(lang)}).finally(()=>{clearTimeout(timer);if(pending.get(lang)===controller)pending.delete(lang);renderCopy()})}
function changeCopy(value){copyLocale=validLanguage(value)||'en';renderCopy();loadCopy()}
const button=text=>{const b=document.createElement('button');b.type='button';b.textContent=text;return b};
const toggle=button('Arrange'),done=button('Done'),reset=button('Reset layout'),back=button('Undo');
toggle.id='ob-arrange-toggle';toggle.setAttribute('aria-expanded','false');
const bar=document.createElement('div');bar.className='ob-arrange-bar';bar.hidden=true;bar.setAttribute('role','region');bar.setAttribute('aria-label','Arrange this Universe');
const status=document.createElement('p');status.setAttribute('role','status');status.className='ob-arrange-status';
bar.append(status,back,reset,done);header.append(toggle);header.append(bar);
const handles=panels.map((panel,i)=>{const b=button(english[['moveHero','moveApps','movePins','moveRecents'][i]]);b.className='ob-arrange-handle';b.hidden=true;b.draggable=true;b.dataset.panel=slots[i];b.setAttribute('aria-pressed','false');panel.prepend(b);b.onclick=()=>choose(i);return b});
function say(id,args={}){lastMessage={id,args};renderCopy()}
function map(){return layouts[current]||slots}
function paint(){panels.forEach((p,i)=>{slots.forEach(s=>p.classList.remove('ob-slot-'+s));p.classList.add('ob-slot-'+map()[i])});handles.forEach((h,i)=>h.setAttribute('aria-pressed',String(selected===i)));back.disabled=!undo}
function save(){try{localStorage.setItem(key,JSON.stringify({version:1,layouts}));return true}catch(_){return false}}
function cancel(){stopScroll();selected=-1;dragged=-1;paint()}
function swap(a,b){stopScroll();if(a<0||b<0||a===b){cancel();return}undo=map().slice();const next=map().slice();[next[a],next[b]]=[next[b],next[a]];layouts[current]=next;selected=-1;dragged=-1;paint();say(save()?'saved':'unsaved');handles[a].focus()}
function choose(i){if(!active)return;if(selected===-1){selected=i;paint();say('selected',{panel:i})}else swap(selected,i)}
function mode(on){stopScroll();active=on;selected=-1;dragged=-1;bar.hidden=!on;handles.forEach(h=>h.hidden=!on);toggle.setAttribute('aria-expanded',String(on));document.body.classList.toggle('ob-arranging',on);paint();if(on){say('instructions');handles[0].focus()}else toggle.focus()}
toggle.onclick=()=>{loadCopy(true);mode(!active)};done.onclick=()=>mode(false);
reset.onclick=()=>{undo=map().slice();delete layouts[current];cancel();say(save()?'resetSaved':'resetUnsaved')};
back.onclick=()=>{if(!undo)return;layouts[current]=undo;undo=null;cancel();say(save()?'undoSaved':'undoUnsaved')};
handles.forEach((h,i)=>{h.addEventListener('dragstart',e=>{if(!active){e.preventDefault();return}dragged=i;selected=i;paint();e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','omnibloom-panel:'+slots[i])});h.addEventListener('dragend',cancel);panels[i].addEventListener('dragover',e=>{if(active&&dragged>=0){e.preventDefault();e.dataTransfer.dropEffect='move'}});panels[i].addEventListener('drop',e=>{if(active&&dragged>=0){e.preventDefault();swap(dragged,i)}})});
window.addEventListener('keydown',e=>{if(!active||document.querySelector('dialog[open]'))return;const index=handles.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(selected>=0){cancel();say('cancelled')}else mode(false);return}if(index<0||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();const from=handles[index].getBoundingClientRect(),fx=from.x+from.width/2,fy=from.y+from.height/2;const candidates=handles.map((h,i)=>{const r=h.getBoundingClientRect(),dx=r.x+r.width/2-fx,dy=r.y+r.height/2-fy;const primary=e.key==='ArrowRight'?dx:e.key==='ArrowLeft'?-dx:e.key==='ArrowDown'?dy:-dy;return{i,primary,score:primary+2*Math.abs(e.key==='ArrowLeft'||e.key==='ArrowRight'?dy:dx)}}).filter(p=>p.i!==index&&p.primary>1).sort((a,b)=>a.score-b.score);if(candidates[0])handles[candidates[0].i].focus()},true);
function sync(){const next=document.body.dataset.obUniverse;if(!ids.includes(next)||next===current)return;stopScroll();current=next;undo=null;selected=-1;dragged=-1;paint();if(active)say('arranging',{universe:next})}
new MutationObserver(sync).observe(document.body,{attributes:true,attributeFilter:['data-ob-universe']});
new MutationObserver(()=>{if(current&&!panels[0].classList.contains('ob-slot-'+map()[0]))paint()}).observe(panels[0],{attributes:true,attributeFilter:['class']});
for(const name of ['omniPadController','omniMediaController']){const previous=window[name];if(typeof previous!=='function')continue;window[name]=function(action){const a=String(action).toLowerCase();if(active&&!document.querySelector('dialog[open]')){if(['circle','back','b'].includes(a)){if(selected>=0){cancel();say('cancelled')}else mode(false);return true}if(handles.includes(document.activeElement)&&['up','down','left','right'].includes(a)){window.dispatchEvent(new KeyboardEvent('keydown',{key:'Arrow'+a[0].toUpperCase()+a.slice(1),cancelable:true}));return true}}return previous.apply(this,arguments)}}
document.addEventListener('dragover',edgeScroll);document.addEventListener('drop',stopScroll,true);document.addEventListener('dragleave',e=>{if(!e.relatedTarget)stopScroll()});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopScroll()});window.addEventListener('pagehide',cancel);sync();
new MutationObserver(()=>changeCopy(document.documentElement.lang)).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
for(const event of ['languagechange','bloom:language-changed','omnibloom:language-changed'])window.addEventListener(event,e=>changeCopy(validLanguage(e.detail?.language)||hostLanguage()||document.documentElement.lang));
window.addEventListener('pagehide',()=>{copyLive=false;for(const controller of pending.values())controller.abort();pending.clear()});window.addEventListener('pageshow',()=>{copyLive=true;renderCopy();loadCopy(true)});renderCopy();loadCopy();
})();


